import java.io.BufferedInputStream
import java.io.PrintWriter
import kotlin.math.min

const val MOD: Int = 998244353

class MInt998244353(private val x: Int) {
    companion object {
        fun zero() = MInt998244353(0)
        fun one() = MInt998244353(1)
        fun from(v: Long): MInt998244353 {
            var t = v % MOD
            if (t < 0) t += MOD
            return MInt998244353(t.toInt())
        }
        private fun modAdd(a: Int, b: Int): Int {
            val s = a + b
            return if (s >= MOD) s - MOD else s
        }
        private fun modSub(a: Int, b: Int): Int {
            return if (a < b) a + MOD - b else a - b
        }
        private fun modMul(a: Int, b: Int): Int {
            return ((a.toLong() * b.toLong()) % MOD).toInt()
        }
        private fun modPow(a: Int, e: Long): Int {
            var x = a.toLong()
            var y = e
            var r = 1L
            while (y > 0) {
                if ((y and 1L) != 0L) r = (r * x) % MOD
                x = (x * x) % MOD
                y = y shr 1
            }
            return r.toInt()
        }
        private fun modInv(a: Int): Int {
            return modPow(a, (MOD - 2).toLong())
        }
    }
    fun inner(): Int = x
    operator fun plus(other: MInt998244353) =
        MInt998244353(modAdd(this.x, other.x))
    operator fun minus(other: MInt998244353) =
        MInt998244353(modSub(this.x, other.x))
    operator fun times(other: MInt998244353) =
        MInt998244353(modMul(this.x, other.x))
    operator fun div(other: MInt998244353) =
        MInt998244353(modMul(this.x, modInv(other.x)))
    operator fun unaryMinus() =
        if (x == 0) this else MInt998244353(MOD - x)
}

typealias M = MInt998244353

class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val bufferSize = 1 shl 16
    private val buffer = ByteArray(bufferSize)
    private var len = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun next(): String {
        val sb = StringBuilder()
        var c = readByte()
        while (c <= 32 && c >= 0) {
            c = readByte()
        }
        while (c > 32) {
