            c = readByte()
        }
        return sb.toString()
    }

    fun nextInt(): Int = next().toInt()
}

class PrimeTable(maxN: Int) {
    private val table: IntArray

    init {
        val size = (maxN + 1) / 2
        table = IntArray(size) { 1 }
        if (size > 0) table[0] = 0
        var i = 3
        while (true) {
            val i2 = i.toLong() * i.toLong()
            if (i2 > maxN.toLong()) break
            if (table[i shr 1] == 1) {
                var j = i2.toInt()
                val step = i * 2
                while (j <= maxN) {
                    val idx = j shr 1
                    if (table[idx] == 1) {
                        table[idx] = i
                    }
                    j += step
                }
            }
            i += 2
        }
    }

    fun isPrime(n: Int): Boolean {
        return n == 2 || (n % 2 == 1 && table[n shr 1] == 1)
    }

    fun forEach(nInput: Int, f: (Int, Int) -> Unit) {
        var n = nInput
        val k = Integer.numberOfTrailingZeros(n)
        if (k > 0) {
            f(2, k)
        }
        n = n ushr k
        while (n > 1 && table[n shr 1] > 1) {
            val p = table[n shr 1]
            var cnt = 1
            n /= p
            while (n > 1 && table[n shr 1] == p) {
                n /= p
                cnt++
            }
            if (n == p) {
                cnt++
                n /= p
            }
            f(p, cnt)
        }
        if (n > 1) {
            f(n, 1)
        }
    }

    fun primeFactors(n: Int): MutableList<Pair<Int, Int>> {
        val factors = mutableListOf<Pair<Int, Int>>()
        forEach(n) { p, c -> factors.add(Pair(p, c)) }
        return factors
    }

    fun countDivisors(n: Int): Int {
        var divisorCnt = 1
        forEach(n) { _, cnt -> divisorCnt *= (cnt + 1) }
        return divisorCnt
    }
}

fun main() {
    val scanner = FastScanner()
    val out = PrintWriter(System.out)
    val n = scanner.nextInt()
    val pt = PrimeTable(n)
    var ans = M.zero()
    var acc = M.zero()
    for (i in 1..n) {
        val c = pt.countDivisors(i)
        ans = acc + M.from(c.toLong())
        acc = acc + ans
    }
    out.println(ans.inner())
    out.flush()
}

