            return if (a < b) a + MOD998244353 - b else a - b
        }
        private fun modMul(a: Int, b: Int): Int {
            return ((a.toLong() * b.toLong()) % MOD998244353).toInt()
        }
        private fun modInv(a: Int): Int {
            var a0 = a.toLong()
            var b0 = MOD998244353.toLong()
            var u = 1L
            var v = 0L
