        MInt998244353(modMul(this.x, other.x))

    operator fun div(other: MInt998244353): MInt998244353 =
        MInt998244353(modMul(this.x, modInv(other.x)))

    operator fun unaryMinus(): MInt998244353 =
        if (x == 0) this else MInt998244353(MOD998244353 - x)

