const val MOD: Long = 998244353L

class MInt(private val x: Long) {
    fun inner(): Long = x

    fun pow(y: Long): MInt {
        var base = x
        var exp = y
        var res = 1L
        while (exp > 0) {
            if ((exp and 1L) == 1L) {
                res = (res * base) % MOD
            }
            base = (base * base) % MOD
            exp = exp shr 1
        }
        return MInt(res)
    }

    fun inv(): MInt {
        return pow(MOD - 2)
    }

    operator fun plus(other: MInt): MInt {
        var z = x + other.x
        if (z >= MOD) z -= MOD
        return MInt(z)
    }

    operator fun minus(other: MInt): MInt {
        var z = x - other.x
        if (z < 0) z += MOD
        return MInt(z)
    }

    operator fun times(other: MInt): MInt {
        return MInt((x * other.x) % MOD)
    }

    operator fun div(other: MInt): MInt {
        return this * other.inv()
    }

    operator fun unaryMinus(): MInt {
        return if (x == 0L) this else MInt(MOD - x)
    }

    companion object {
        fun zero() = MInt(0L)
        fun one() = MInt(1L)
        fun from(v: Long) = MInt(((v % MOD) + MOD) % MOD)
        fun from(v: Int) = from(v.toLong())
    }
}

class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val bufferSize = 1 shl 16
    private val buffer = ByteArray(bufferSize)
    private var len = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextInt(): Int {
        var c = readByte()
        while (c <= 32 && c >= 0) c = readByte()
        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }
        var res = 0
        while (c > 32) {
            res = res * 10 + (c - '0'.code)
            c = readByte()
        }
        return res * sign
    }
}

