            if ((exp and 1L) == 1L) {
                res = (res * base) % MOD
            }
            base = (base * base) % MOD
            exp = exp shr 1
        }
        return MInt(res)
    }

    fun inv(): MInt {
        return pow(MOD - 2)
    }

    operator fun plus(other: MInt): MInt {
