    private val table: IntArray

    init {
        val size = (maxN + 1) / 2
        table = IntArray(size) { 1 }
        if (size > 0) table[0] = 0
        var i = 3
        while (true) {
            val i2 = i.toLong() * i.toLong()
            if (i2 > maxN.toLong()) break
            if (table[i shr 1] == 1) {
                var j = i2.toInt()
                val step = i * 2
                while (j <= maxN) {
                    val idx = j shr 1
                    if (table[idx] == 1) {
                        table[idx] = i
                    }
                    j += step
                }
            }
            i += 2
        }
    }

    fun isPrime(n: Int): Boolean {
        return n == 2 || (n % 2 == 1 && table[n shr 1] == 1)
    }

    private inline fun forEach(nInput: Int, f: (Int, Int) -> Unit) {
        var n = nInput
        val k = Integer.numberOfTrailingZeros(n)
        if (k > 0) {
            f(2, k)
        }
        n = n ushr k
        while (table[n shr 1] > 1) {
            val p = table[n shr 1]
            var cnt = 1
            n /= p
            while (table[n shr 1] == p) {
                n /= p
                cnt++
            }
            if (n == p) {
                cnt++
                n /= p
            }
            f(p, cnt)
        }
        if (n > 1) {
            f(n, 1)
        }
    }

    fun primeFactors(n: Int): List<Pair<Int, Int>> {
        val factors = ArrayList<Pair<Int, Int>>()
        forEach(n) { p, c -> factors.add(Pair(p, c)) }
        return factors
    }

    fun countDivisors(n: Int): Int {
        var divisorCnt = 1
        forEach(n) { _, cnt -> divisorCnt *= (cnt + 1) }
        return divisorCnt
    }
}

